# Yae 3[E] > Odette 2[E] > Beidou shE(ур. 1) Q > Wriothesley [combo]; комбо Ризли — как в конфигах базы gcsim.
# Билды — по нашим гайдам (src/content/builds), доп. статы подбирает оптимизатор gcsim.
odette char lvl=90/90 cons=0 talent=9,9,9;
odette add weapon="finaleofthedeep" refine=5 lvl=90/90;
odette add set="heartofthefurnace" count=4;
odette add stats hp=4780 atk=311 atk%=0.466 atk%=0.466 cr=0.311;
odette add stats def%=0.062*2 def=19.68*2 hp=253.94*2 hp%=0.0496*2 atk=16.54*2 atk%=0.0496*2 er=0.0551*2 em=19.82*4 cr=0.0331*10 cd=0.0662*12;
yaemiko char lvl=90/90 cons=0 talent=9,9,9;
yaemiko add weapon="solarpearl" refine=5 lvl=90/90;
yaemiko add set="emblemofseveredfate" count=4;
yaemiko add stats hp=4780 atk=311 er=0.518 electro%=0.466 cr=0.311;
yaemiko add stats def%=0.062*2 def=19.68*2 hp=253.94*2 hp%=0.0496*2 atk=16.54*2 atk%=0.0496*12 er=0.0551*2 em=19.82*2 cr=0.0331*2 cd=0.0662*12;
wriothesley char lvl=90/90 cons=0 talent=9,9,9;
wriothesley add weapon="flowingpurity" refine=5 lvl=90/90;
wriothesley add set="marechausseehunter" count=4;
wriothesley add stats hp=4780 atk=311 atk%=0.466 cryo%=0.466 cr=0.311;
wriothesley add stats def%=0.062*2 def=19.68*2 hp=253.94*2 hp%=0.0496*2 atk=16.54*2 atk%=0.0496*10 er=0.0551*2 em=19.82*2 cr=0.0331*4 cd=0.0662*12;
beidou char lvl=90/90 cons=6 talent=9,9,9;
beidou add weapon="serpentspine" refine=5 lvl=90/90;
beidou add set="emblemofseveredfate" count=4;
beidou add stats hp=4780 atk=311 atk%=0.466 electro%=0.466 cr=0.311;
beidou add stats def%=0.062*2 def=19.68*2 hp=253.94*2 hp%=0.0496*2 atk=16.54*2 atk%=0.0496*2 er=0.0551*12 em=19.82*2 cr=0.0331*2 cd=0.0662*12;
options swap_delay=12;
target lvl=100 resist=0.1 radius=2 pos=0,2.4 hp=999999999;
energy every interval=480,720 amount=1;
active yaemiko;
for let i=0; i<4; i=i+1 {
  if .yaemiko.burst.ready {
    yaemiko burst;
  }
  yaemiko skill:3;
  odette skill, skill;
  beidou skill[counter=1], burst;
  wriothesley skill,
    attack:5, charge, jump,
    attack:5, charge, jump,
    attack:5, charge, jump,
    attack:5, charge;
}

